  -- 01. Introducción al curso: farmacología endocrina para el QF en Colombia
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La hormona que se ajusta con datos","texto":"Una paciente con hipotiroidismo cambia de marca de levotiroxina y vuelve con TSH alta. La farmacología endocrina exige entender absorción, interacciones y metas. El químico farmacéutico puede detectar lo que la fórmula no dice."},"objetivos":["Reconocer el alcance de la farmacología endocrina.","Identificar el rol del QF.","Conocer las guías de referencia.","Aplicar el contexto colombiano."],"conceptos":[{"icono":"Activity","termino":"Endocrinología","definicion":"Hormonas, ejes y metabolismo."},{"icono":"Pill","termino":"Farmacoterapia","definicion":"Selección, ajuste y seguimiento."},{"icono":"Users","termino":"Educación","definicion":"Técnica, adherencia y autocuidado."},{"icono":"Landmark","termino":"PBS","definicion":"Cobertura de medicamentos en Colombia."}],"secciones":[{"titulo":"Por qué este curso","parrafos":["La farmacología endocrina abarca la diabetes, la obesidad, las enfermedades tiroideas, los glucocorticoides, la osteoporosis, la hipófisis y las hormonas sexuales. Son tratamientos crónicos, con ajustes frecuentes y un alto impacto en la calidad de vida.","El curso integra las guías colombianas, la ADA Standards of Care 2026, la evidencia internacional y el contexto del PBS, MIPRES y la farmacovigilancia del INVIMA. Cada clase termina con un caso aplicado y una intervención del químico farmacéutico."]},{"titulo":"El rol del QF","parrafos":["El QF participa en la dispensación informada, la educación sobre técnica y adherencia, la revisión de interacciones y el seguimiento farmacoterapéutico. En diabetes, ayuda con la insulina, los dispositivos y la hipoglucemia. En tiroides, con la absorción y las interacciones. En osteoporosis, con la adherencia y la secuencia.","También detecta problemas relacionados con medicamentos, propone ajustes y reporta reacciones adversas. La farmacología endocrina exige leer laboratorios y tendencias, no solo la receta del día."]},{"titulo":"Guías y contexto","parrafos":["Las referencias son la Guía de Práctica Clínica de diabetes del Ministerio de Salud, la ADA Standards of Care 2026, las guías de tiroides y osteoporosis y las fichas técnicas aprobadas por el INVIMA. En Colombia se suman el PBS, los mecanismos de acceso y las rutas de atención.","La meta es formar criterio para elegir, ajustar y educar con seguridad. La endocrinología requiere paciencia y seguimiento: los cambios se miden en semanas o meses, y la adherencia es determinante."]}],"errores":[{"error":"Ver solo la receta.","correccion":"La adherencia y la absorción importan."},{"error":"Ignorar el contexto de acceso.","correccion":"El PBS condiciona la continuidad."},{"error":"No educar sobre técnica.","correccion":"Es clave en insulina y osteo."}],"comprueba":[{"pregunta":"¿Qué áreas cubre el curso?","respuesta":"Diabetes, tiroides, hueso, hormonas y obesidad."},{"pregunta":"¿Qué guía de diabetes se usa?","respuesta":"La GPC MinSalud y ADA 2026."},{"pregunta":"¿Qué aporta el QF?","respuesta":"Educación, revisión y seguimiento."}],"resumen":["La endocrinología es crónica y ajustable.","El QF interviene en todo el ciclo.","Las guías y el contexto colombiano se integran.","Cada clase termina en un caso."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"Ministerio de Salud y Protección Social. Guía de práctica clínica de diabetes mellitus tipo 2. Bogotá.","url":"https://www.minsalud.gov.co/"}],"imagenes":[{"ubicacion":"Introducción","descripcion":"Farmacéutico revisando un esquema endocrino.","alt":"Introducción a la farmacología endocrina"}],"keywords":["farmacología endocrina","rol químico farmacéutico","diabetes","tiroides"],"mapa":{"centro":"Farmacología endocrina","ramas":[{"titulo":"Diabetes","icono":"TestTube","nodos":["Insulina","Metformina","GLP-1","SGLT2"]},{"titulo":"Tiroides","icono":"Activity","nodos":["Levotiroxina","Metimazol","PTU"]},{"titulo":"Hueso","icono":"ShieldCheck","nodos":["Calcio","Bisfosfonatos","Denosumab"]},{"titulo":"Hormonas","icono":"Users","nodos":["Glucocorticoides","Sexuales","Hipófisis"]}]},"proceso":{"titulo":"Cómo estudiar el curso","intro":"","pasos":[{"titulo":"Contextualizar","detalle":"Leer el caso y la meta.","icono":"Target","evidencia":"Meta."},{"titulo":"Comprender","detalle":"Mecanismo y ejes.","icono":"BookOpen","evidencia":"Notas."},{"titulo":"Aplicar","detalle":"Resolver el caso.","icono":"Workflow","evidencia":"Decisión."},{"titulo":"Verificar","detalle":"Responder las comprobaciones.","icono":"ClipboardCheck","evidencia":"Resultado."},{"titulo":"Transferir","detalle":"Llevarlo a la práctica.","icono":"Repeat","evidencia":"Plan."}]},"caso":{"titulo":"Cambio de marca de levotiroxina","contexto":"Paciente con hipotiroidismo estable que cambia de marca y presenta TSH elevada.","pregunta":"¿Qué revisa el QF?","opciones":[{"texto":"Solo la dosis.","correcta":false,"retro":"La absorción y la marca importan."},{"texto":"Absorción, interacciones y adherencia.","correcta":true,"retro":"Explica el cambio de TSH."},{"texto":"Suspender el tratamiento.","correcta":false,"retro":"Empeoraría el hipotiroidismo."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
