  -- 02. Fisiopatología de la DM1 y DM2 y dianas farmacológicas
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Dos diabetes, dos lógicas","texto":"En la DM1 falta insulina por destrucción autoinmune; en la DM2 hay resistencia y falla progresiva de la célula beta. Entender la diferencia explica por qué la insulina es indispensable en una y no siempre en la otra."},"objetivos":["Diferenciar la DM1 y la DM2.","Reconocer las dianas farmacológicas.","Conectar fisiopatología y tratamiento.","Aplicar el concepto de falla progresiva."],"conceptos":[{"icono":"ShieldCheck","termino":"DM1","definicion":"Destrucción autoinmune de la célula beta."},{"icono":"Activity","termino":"DM2","definicion":"Resistencia a la insulina y falla beta."},{"icono":"Database","termino":"Incretinas","definicion":"GLP-1 y GIP; efecto sobre la insulina."},{"icono":"Droplets","termino":"SGLT2","definicion":"Reabsorción renal de glucosa."}],"secciones":[{"titulo":"DM1","parrafos":["La diabetes tipo 1 es una enfermedad autoinmune en la que las células beta del páncreas se destruyen y la insulina falta de forma absoluta. Puede presentarse con cetoacidosis. El tratamiento es la insulina desde el diagnóstico, con esquemas basal-bolo o bomba.","La fisiopatología explica la necesidad de contar carbohidratos, ajustar dosis y prevenir hipoglucemias. La educación y la tecnología son parte del tratamiento, no un complemento."]},{"titulo":"DM2","parrafos":["La diabetes tipo 2 combina resistencia a la insulina en músculo, hígado y tejido adiposo con una falla progresiva de la célula beta. También hay defecto de incretinas, exceso de glucagón, mayor reabsorción renal de glucosa e inflamación. La enfermedad es heterogénea y cambia con el tiempo.","Las dianas farmacológicas reflejan esa fisiopatología: metformina reduce la producción hepática de glucosa; sulfonilureas estimulan la insulina; pioglitazona mejora la sensibilidad; los inhibidores de DPP-4 y los agonistas de GLP-1 actúan sobre las incretinas; los iSGLT2 aumentan la glucosuria; la insulina reemplaza la deficiencia."]},{"titulo":"Consecuencias clínicas","parrafos":["La falla progresiva explica por qué muchos pacientes necesitan intensificar el tratamiento con el tiempo. No es un fracaso del paciente ni del médico. La elección se centra en las comorbilidades: enfermedad cardiovascular, insuficiencia cardíaca, enfermedad renal y obesidad.","El QF traduce la fisiopatología en educación: por qué se toma cada fármaco, qué esperar y cómo reconocer la hipoglucemia. La comprensión mejora la adherencia y la seguridad."]}],"errores":[{"error":"Tratar la DM1 sin insulina.","correccion":"Riesgo de cetoacidosis."},{"error":"Creer que la DM2 es estática.","correccion":"Es progresiva."},{"error":"Elegir sin comorbilidad.","correccion":"La diana importa."}],"comprueba":[{"pregunta":"¿Qué falta en la DM1?","respuesta":"Insulina de forma absoluta."},{"pregunta":"¿Qué caracteriza la DM2?","respuesta":"Resistencia y falla beta progresiva."},{"pregunta":"¿Qué fármaco reduce la glucosa hepática?","respuesta":"La metformina."}],"resumen":["DM1 y DM2 tienen fisiopatologías distintas.","La DM2 es progresiva y heterogénea.","Las dianas explican los fármacos.","La educación traduce el mecanismo."],"referencias":[{"cita":"American Diabetes Association. 2. Diagnosis and Classification of Diabetes: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Fisiopatología","descripcion":"Comparación de DM1 y DM2 con sus dianas.","alt":"Fisiopatología de la diabetes tipo 1 y tipo 2"}],"keywords":["fisiopatología diabetes","dm1","dm2","incretinas","sglt2"],"mapa":{"centro":"Fisiopatología","ramas":[{"titulo":"DM1","icono":"ShieldCheck","nodos":["Autoinmune","Déficit absoluto","Insulina"]},{"titulo":"DM2","icono":"Activity","nodos":["Resistencia","Falla beta","Incretinas"]},{"titulo":"Hígado","icono":"Database","nodos":["Gluconeogénesis","Metformina"]},{"titulo":"Riñón","icono":"Droplets","nodos":["SGLT2","Glucosuria","Beneficio"]}]},"proceso":{"titulo":"Del mecanismo al fármaco","intro":"","pasos":[{"titulo":"Tipo","detalle":"DM1 o DM2.","icono":"Search","evidencia":"Diagnóstico."},{"titulo":"Mecanismo","detalle":"Déficit o resistencia.","icono":"BookOpen","evidencia":"Notas."},{"titulo":"Diana","detalle":"Hígado, beta, riñón o incretinas.","icono":"Target","evidencia":"Fármaco."},{"titulo":"Elegir","detalle":"Comorbilidad y meta.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Educar","detalle":"Propósito y seguridad.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"DM1 de inicio","contexto":"Joven con sed, poliuria, pérdida de peso y cetonas.","pregunta":"¿Qué tratamiento es indispensable?","opciones":[{"texto":"Metformina.","correcta":false,"retro":"No reemplaza la insulina."},{"texto":"Insulina.","correcta":true,"retro":"Hay déficit absoluto."},{"texto":"Solo dieta.","correcta":false,"retro":"No es suficiente."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
