  -- 03. Metas glucémicas y guías: GPC MinSalud/IETS y ADA Standards of Care 2026
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La meta no es la misma para todos","texto":"Un adulto joven sin complicaciones y un anciano frágil con hipoglucemias no comparten la misma meta de HbA1c. Individualizar evita el daño por sobretratamiento y por abandono."},"objetivos":["Aplicar metas individualizadas.","Interpretar HbA1c y tiempo en rango.","Reconocer las guías de referencia.","Ajustar según riesgo de hipoglucemia."],"conceptos":[{"icono":"Target","termino":"HbA1c","definicion":"Promedio de glucosa de 2-3 meses."},{"icono":"Timer","termino":"Tiempo en rango","definicion":"Porcentaje de glucosa entre 70 y 180."},{"icono":"Users","termino":"Individualización","definicion":"Meta según edad y comorbilidad."},{"icono":"AlertTriangle","termino":"Hipoglucemia","definicion":"Límite del tratamiento intensivo."}],"secciones":[{"titulo":"Metas","parrafos":["La meta general de HbA1c es menor de 7 % para muchos adultos no embarazadas. Se individualiza: más estricta en pacientes jóvenes, con poca comorbilidad y bajo riesgo de hipoglucemia; menos estricta en ancianos frágiles, con comorbilidades graves o hipoglucemias recurrentes. La meta se acuerda con el paciente.","El tiempo en rango, medido con monitorización continua, complementa la HbA1c. Un tiempo en rango mayor de 70 % entre 70 y 180 mg/dL se considera adecuado para muchos pacientes. La variabilidad y el tiempo en hipoglucemia también importan."]},{"titulo":"Guías","parrafos":["La Guía de Práctica Clínica colombiana y la ADA Standards of Care 2026 coinciden en la individualización, el enfoque en comorbilidades y la importancia de la educación. La ADA actualiza cada año las recomendaciones de tratamiento y tecnología.","Las guías no sustituyen el juicio clínico. El QF revisa si la meta es realista, si el esquema puede alcanzarla sin hipoglucemia y si el paciente comprende el plan."]},{"titulo":"Aplicación","parrafos":["El QF revisa la HbA1c, el tiempo en rango, el uso de rescate y las hipoglucemias. Si la meta no se alcanza, revisa adherencia, técnica, dosis y barreras. Si hay hipoglucemias, revisa el esquema y la educación antes de intensificar.","La meta debe medirse y reevaluarse. Un cambio de tratamiento sin seguimiento es una oportunidad perdida. La educación sobre qué significa la HbA1c mejora la participación del paciente."]}],"errores":[{"error":"Aplicar 7 % a todos.","correccion":"La meta se individualiza."},{"error":"Ignorar las hipoglucemias.","correccion":"Son un límite del tratamiento."},{"error":"No medir el tiempo en rango.","correccion":"Complementa la HbA1c."}],"comprueba":[{"pregunta":"¿Cuál es la meta general?","respuesta":"HbA1c menor de 7 %."},{"pregunta":"¿Qué es el tiempo en rango?","respuesta":"Porcentaje entre 70 y 180 mg/dL."},{"pregunta":"¿Qué población requiere metas menos estrictas?","respuesta":"Ancianos frágiles o con hipoglucemias."}],"resumen":["La meta se individualiza.","La HbA1c y el TIR se complementan.","Las guías orientan, no imponen.","La hipoglucemia limita la intensificación."],"referencias":[{"cita":"American Diabetes Association. 6. Glycemic Goals and Hypoglycemia: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Metas","descripcion":"Metas de HbA1c según perfil del paciente.","alt":"Metas glucémicas individualizadas"}],"keywords":["hba1c","metas glucémicas","tiempo en rango","ada 2026"],"mapa":{"centro":"Metas glucémicas","ramas":[{"titulo":"HbA1c","icono":"Target","nodos":["<7 %","Individualizar","Riesgo"]},{"titulo":"TIR","icono":"Timer","nodos":[">70 %","CGM","Variabilidad"]},{"titulo":"Guías","icono":"BookOpen","nodos":["GPC MinSalud","ADA 2026"]},{"titulo":"Poblaciones","icono":"Users","nodos":["Joven","Anciano","Frágil"]}]},"proceso":{"titulo":"Definir la meta","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Edad, comorbilidad y riesgo.","icono":"ClipboardList","evidencia":"Ficha."},{"titulo":"Medir","detalle":"HbA1c y TIR.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Acordar","detalle":"Meta realista.","icono":"Users","evidencia":"Acuerdo."},{"titulo":"Tratar","detalle":"Esquema y educación.","icono":"Pill","evidencia":"Plan."},{"titulo":"Reevaluar","detalle":"Control y ajuste.","icono":"Repeat","evidencia":"Seguimiento."}]},"caso":{"titulo":"Anciano frágil","contexto":"Paciente de 84 años, frágil, con hipoglucemias recurrentes y HbA1c de 6,5 %.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Intensificar para bajar más.","correcta":false,"retro":"El riesgo de hipoglucemia es alto."},{"texto":"Relajar la meta y revisar el esquema.","correcta":true,"retro":"La seguridad es prioritaria."},{"texto":"Suspender todo tratamiento.","correcta":false,"retro":"Se pierde el control."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Metas glucémicas y guías: GPC MinSalud/IETS y ADA Standards of Care 2026$t$ AND deleted_at IS NULL
