  -- 04. Tipos de insulina y perfiles de acción
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Rápida, basal o intermedia","texto":"Un paciente recibe insulina rápida en lugar de basal y presenta hipoglucemias nocturnas. El perfil de acción explica el error. Conocer inicio, pico y duración es indispensable para dispensar con seguridad."},"objetivos":["Clasificar las insulinas.","Aplicar inicio, pico y duración.","Elegir según el esquema.","Prevenir errores de dispensación."],"conceptos":[{"icono":"Zap","termino":"Rápida","definicion":"Análogos que actúan en minutos."},{"icono":"Timer","termino":"Basal","definicion":"Efecto estable y prolongado."},{"icono":"Pill","termino":"NPH","definicion":"Intermedia con pico."},{"icono":"Layers","termino":"Premezclada","definicion":"Combinación fija."}],"secciones":[{"titulo":"Clasificación","parrafos":["Las insulinas se clasifican por su inicio y duración. Los análogos de acción rápida (lispro, asparta, glulisina) empiezan en minutos y cubren las comidas. La insulina regular empieza más lento y se aplica unos 30 minutos antes; es la de uso intravenoso hospitalario.","La NPH es intermedia, tiene un pico y se usa una o dos veces al día, con riesgo de hipoglucemia nocturna. Los análogos basales (glargina, detemir, degludec) tienen un efecto más estable y prolongado, con menos hipoglucemia. Las premezcladas combinan una intermedia con una rápida en proporción fija."]},{"titulo":"Elección y seguridad","parrafos":["En la diabetes tipo 1 se prefieren análogos rápidos y basales para reducir hipoglucemias. En la tipo 2, la NPH y la regular siguen siendo útiles por costo, con vigilancia. La concentración importa: existen insulinas de 100 U/mL y de 300 U/mL, y no son intercambiables sin ajuste.","El QF verifica el nombre, la concentración, la presentación y el dispositivo. Los errores entre insulinas de aspecto similar son frecuentes y peligrosos. La separación física y el rotulado por colores reducen el riesgo."]},{"titulo":"Educación","parrafos":["El paciente debe saber qué insulina es basal y cuál es prandial, cuándo aplicarla y qué hacer si olvida una dosis. La educación se adapta al esquema y al dispositivo. La revisión de la técnica y de los sitios de inyección es parte del seguimiento.","La insulina es un medicamento de alto riesgo. La claridad en la dispensación y la verificación de la comprensión evitan eventos graves."]}],"errores":[{"error":"Confundir concentraciones.","correccion":"100 y 300 U/mL no son iguales."},{"error":"No revisar el horario.","correccion":"La rápida se usa antes de comer."},{"error":"No separar insulinas similares.","correccion":"Favorece errores."}],"comprueba":[{"pregunta":"¿Qué insulina actúa en minutos?","respuesta":"Los análogos rápidos."},{"pregunta":"¿Qué insulina tiene pico?","respuesta":"La NPH."},{"pregunta":"¿Qué se verifica al dispensar?","respuesta":"Tipo, concentración y dispositivo."}],"resumen":["Cada insulina tiene un perfil distinto.","Las basales son estables; la NPH tiene pico.","La concentración no es intercambiable.","La verificación evita errores graves."],"referencias":[{"cita":"American Diabetes Association. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://doi.org/10.2337/dc26-S009"}],"imagenes":[{"ubicacion":"Insulinas","descripcion":"Perfiles de acción de las insulinas.","alt":"Tipos de insulina y perfiles de acción"}],"keywords":["tipos de insulina","insulina basal","nph","insulina rápida"],"mapa":{"centro":"Insulinas","ramas":[{"titulo":"Rápidas","icono":"Zap","nodos":["Lispro","Asparta","Glulisina"]},{"titulo":"Corta","icono":"Pill","nodos":["Regular","30 min antes","IV"]},{"titulo":"Basales","icono":"Timer","nodos":["Glargina","Detemir","Degludec"]},{"titulo":"Intermedia","icono":"Layers","nodos":["NPH","Pico","Dos veces"]}]},"proceso":{"titulo":"Verificar la insulina","intro":"","pasos":[{"titulo":"Tipo","detalle":"Basal, rápida o intermedia.","icono":"Search","evidencia":"Fórmula."},{"titulo":"Concentración","detalle":"100 o 300 U/mL.","icono":"AlertTriangle","evidencia":"Etiqueta."},{"titulo":"Horario","detalle":"Antes de comer o basal.","icono":"Timer","evidencia":"Esquema."},{"titulo":"Dispositivo","detalle":"Pluma y aguja.","icono":"Package","evidencia":"Revisión."},{"titulo":"Educar","detalle":"Dosis y olvidos.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Rápida en lugar de basal","contexto":"Paciente que recibe insulina rápida en la noche por confusión con la basal.","pregunta":"¿Qué riesgo presenta?","opciones":[{"texto":"Hiperglucemia leve.","correcta":false,"retro":"La rápida produce hipoglucemia."},{"texto":"Hipoglucemia nocturna grave.","correcta":true,"retro":"El pico ocurre en horas."},{"texto":"Ninguno.","correcta":false,"retro":"Es un error de alto riesgo."}]}}$j$::jsonb;
