  -- 05. Esquemas de insulinización: basal, basal-plus y basal-bolo
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Empezar por la basal","texto":"En la DM2, la insulina basal es el inicio más simple. En la DM1, el esquema basal-bolo es la norma. La elección depende del tipo de diabetes, la HbA1c y la capacidad del paciente."},"objetivos":["Aplicar los esquemas de insulinización.","Calcular dosis iniciales.","Titular según glucosa.","Elegir según el paciente."],"conceptos":[{"icono":"Timer","termino":"Basal","definicion":"Insulina de fondo, una o dos veces al día."},{"icono":"Layers","termino":"Basal-plus","definicion":"Basal más una dosis prandial."},{"icono":"Activity","termino":"Basal-bolo","definicion":"Basal más bolos en cada comida."},{"icono":"Calculator","termino":"Titulación","definicion":"Ajuste según glucosa."}],"secciones":[{"titulo":"Esquemas","parrafos":["En la DM2 con hiperglucemia, la insulina basal es el inicio habitual: 10 unidades al día o 0,1-0,2 U/kg, titulada según la glucosa de ayunas. Si la HbA1c está muy elevada o hay síntomas, se puede iniciar un esquema más intensivo. La combinación con agonistas GLP-1 reduce la dosis y el peso.","El basal-plus añade una dosis prandial a la comida principal. El basal-bolo usa insulina basal más bolos antes de cada comida y es el esquema de la DM1. La proporción inicial suele ser 50 % basal y 50 % prandial, con ajuste según el conteo de carbohidratos y la glucosa."]},{"titulo":"Titulación","parrafos":["La insulina basal se titula cada tres días según la glucosa de ayunas, con ajustes de 2 unidades o 10-20 % hasta alcanzar la meta sin hipoglucemia. Los bolos se ajustan según la glucosa preprandial y posprandial, el conteo de carbohidratos y la actividad.","La hipoglucemia obliga a revisar la dosis y el horario. La educación sobre el conteo, la corrección y el ejercicio es esencial. La tecnología, como el monitoreo continuo, facilita la titulación."]},{"titulo":"Elección","parrafos":["La elección depende del tipo de diabetes, la HbA1c, la edad, la capacidad de autocuidado y el soporte familiar. En la DM1 no se debe retrasar el esquema basal-bolo. En la DM2 se avanza según la respuesta y las preferencias.","El QF revisa la coherencia del esquema, la técnica y la comprensión. La insulina no es un castigo: es una herramienta eficaz cuando se usa con educación y seguimiento. La revisión periódica de la dosis y del registro de glucosa evita ajustes tardíos y mejora la seguridad."]}],"errores":[{"error":"No titular la basal.","correccion":"Se queda corta."},{"error":"Usar basal-bolo sin educación.","correccion":"Riesgo de hipoglucemia."},{"error":"Retrasar la insulina en DM1.","correccion":"Riesgo de cetoacidosis."}],"comprueba":[{"pregunta":"¿Dosis inicial de basal?","respuesta":"10 U o 0,1-0,2 U/kg."},{"pregunta":"¿Cada cuánto se titula?","respuesta":"Cada tres días."},{"pregunta":"¿Qué esquema usa la DM1?","respuesta":"Basal-bolo."}],"resumen":["La basal es el inicio en DM2.","El basal-bolo es la norma en DM1.","La titulación es progresiva.","La educación sostiene el esquema."],"referencias":[{"cita":"American Diabetes Association. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://doi.org/10.2337/dc26-S009"}],"imagenes":[{"ubicacion":"Esquemas","descripcion":"Comparación de basal, basal-plus y basal-bolo.","alt":"Esquemas de insulinización"}],"keywords":["insulinización","basal-bolo","basal-plus","titulación insulina"],"mapa":{"centro":"Insulinización","ramas":[{"titulo":"Basal","icono":"Timer","nodos":["10 U","0,1-0,2 U/kg","Titular"]},{"titulo":"Basal-plus","icono":"Layers","nodos":["Una comida","Rescate","Simplificar"]},{"titulo":"Basal-bolo","icono":"Activity","nodos":["50/50","Conteo","DM1"]},{"titulo":"Titulación","icono":"Calculator","nodos":["Ayunas","Cada 3 días","Hipoglucemia"]}]},"proceso":{"titulo":"Iniciar insulina","intro":"","pasos":[{"titulo":"Tipo","detalle":"DM1 o DM2.","icono":"Search","evidencia":"Diagnóstico."},{"titulo":"Esquema","detalle":"Basal o basal-bolo.","icono":"Layers","evidencia":"Plan."},{"titulo":"Dosis","detalle":"Peso y glucosa.","icono":"Calculator","evidencia":"Fórmula."},{"titulo":"Titular","detalle":"Cada 3 días.","icono":"LineChart","evidencia":"Registro."},{"titulo":"Educar","detalle":"Hipoglucemia y técnica.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"DM2 con HbA1c alta","contexto":"Paciente con DM2, HbA1c de 10 % y síntomas, sin insulina.","pregunta":"¿Qué esquema se considera?","opciones":[{"texto":"Insulina basal o esquema intensivo según el caso.","correcta":true,"retro":"La hiperglucemia grave lo requiere."},{"texto":"Solo metformina.","correcta":false,"retro":"No es suficiente."},{"texto":"Suspender el tratamiento.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
