  -- 06. Dispositivos, técnica de inyección y conservación de la insulina
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La lipohipertrofia que cambia la absorción","texto":"Un paciente inyecta siempre en el mismo punto y desarrolla lipohipertrofia. La absorción se vuelve irregular y el control empeora. Rotar los sitios y revisar la técnica es parte del tratamiento."},"objetivos":["Aplicar la técnica de inyección.","Reconocer sitios y rotación.","Conservar la insulina correctamente.","Educar sobre dispositivos y residuos."],"conceptos":[{"icono":"Package","termino":"Pluma","definicion":"Dispositivo de dosis ajustable."},{"icono":"AlertTriangle","termino":"Lipohipertrofia","definicion":"Acumulación de grasa por repetición."},{"icono":"Timer","termino":"Conservación","definicion":"2-8 °C sin congelar."},{"icono":"Users","termino":"Rotación","definicion":"Cambiar el sitio de inyección."}],"secciones":[{"titulo":"Técnica","parrafos":["La insulina se inyecta en el tejido subcutáneo del abdomen, muslo, brazo o glúteo. Se recomienda aguja de 4-6 mm y ángulo de 90° o 45° según el grosor del tejido. Se debe sostener la aguja unos segundos después de la inyección y no masajear la zona.","La rotación de sitios dentro de la misma región previene la lipohipertrofia, que altera la absorción y produce hipoglucemias o hiperglucemias inexplicables. La revisión de los sitios es parte del seguimiento."]},{"titulo":"Dispositivos","parrafos":["Las plumas son cómodas y precisas, pero requieren cebado, aguja nueva y verificación de la dosis. Las jeringas se usan cuando no hay pluma o en dosis especiales. Las bombas y los sistemas automatizados requieren educación avanzada.","El QF verifica que el paciente sepa cargar la pluma, cambiar la aguja y desecharla en un contenedor de punzantes. La técnica incorrecta es una causa frecuente de mal control."]},{"titulo":"Conservación","parrafos":["La insulina sin abrir se conserva entre 2 y 8 °C, sin congelar. La pluma en uso puede mantenerse a temperatura ambiente por un período limitado, según la ficha técnica, y no debe exponerse al calor extremo ni al sol directo.","La insulina congelada o expuesta a altas temperaturas pierde efecto. El paciente debe revisar la apariencia y la fecha. La educación sobre conservación es especialmente importante en zonas con clima cálido. También se revisa que la pluma no esté caducada y que la aguja se cambie en cada aplicación."]}],"errores":[{"error":"No rotar los sitios.","correccion":"Causa lipohipertrofia."},{"error":"Congelar la insulina.","correccion":"Pierde efecto."},{"error":"Reutilizar agujas indefinidamente.","correccion":"Dolor y lesión."}],"comprueba":[{"pregunta":"¿Dónde se inyecta?","respuesta":"Tejido subcutáneo."},{"pregunta":"¿Qué causa no rotar?","respuesta":"Lipohipertrofia."},{"pregunta":"¿Cómo se conserva sin abrir?","respuesta":"Entre 2 y 8 °C."}],"resumen":["La técnica correcta mejora la absorción.","La rotación previene la lipohipertrofia.","La conservación mantiene la potencia.","Los residuos se desechan con seguridad."],"referencias":[{"cita":"American Diabetes Association. 7. Diabetes Technology: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Técnica","descripcion":"Sitios de inyección y rotación.","alt":"Técnica de inyección y conservación de insulina"}],"keywords":["técnica insulina","lipohipertrofia","conservación insulina","pluma"],"mapa":{"centro":"Técnica de insulina","ramas":[{"titulo":"Dispositivo","icono":"Package","nodos":["Pluma","Aguja","Dosis"]},{"titulo":"Sitios","icono":"Users","nodos":["Abdomen","Muslo","Brazo","Rotación"]},{"titulo":"Técnica","icono":"Eye","nodos":["Ángulo","Sostener","No masajear"]},{"titulo":"Conservación","icono":"Timer","nodos":["2-8 °C","28 días","No congelar"]}]},"proceso":{"titulo":"Enseñar la técnica","intro":"","pasos":[{"titulo":"Dispositivo","detalle":"Pluma y aguja.","icono":"Package","evidencia":"Revisión."},{"titulo":"Sitio","detalle":"Rotación y revisión.","icono":"Users","evidencia":"Demostración."},{"titulo":"Inyección","detalle":"Ángulo y sostén.","icono":"Eye","evidencia":"Práctica."},{"titulo":"Conservación","detalle":"Temperatura y fecha.","icono":"Timer","evidencia":"Consejería."},{"titulo":"Residuos","detalle":"Contenedor de punzantes.","icono":"Trash2","evidencia":"Entrega."}]},"caso":{"titulo":"Siempre en el mismo punto","contexto":"Paciente con control irregular que inyecta siempre en la misma zona y tiene una zona indurada.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Aumentar la dosis.","correcta":false,"retro":"La absorción es irregular."},{"texto":"Enseñar rotación y revisar la técnica.","correcta":true,"retro":"Corrige la causa."},{"texto":"Suspender la insulina.","correcta":false,"retro":"No es seguro."}]}}$j$::jsonb;
