  -- 07. Hipoglucemia: clasificación, causas farmacológicas y tratamiento
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La regla de los 15","texto":"Un paciente con glucosa de 55 mg/dL y temblor necesita 15 gramos de carbohidrato y reevaluación en 15 minutos. La hipoglucemia es el límite del tratamiento y una emergencia prevenible."},"objetivos":["Clasificar la hipoglucemia.","Reconocer causas farmacológicas.","Aplicar la regla de los 15.","Prevenir episodios graves."],"conceptos":[{"icono":"AlertTriangle","termino":"Nivel 1","definicion":"Glucosa menor de 70 mg/dL."},{"icono":"Timer","termino":"Nivel 2","definicion":"Glucosa menor de 54 mg/dL."},{"icono":"Pill","termino":"Glucagón","definicion":"Tratamiento de la hipoglucemia grave."},{"icono":"Users","termino":"Prevención","definicion":"Educación y ajuste del esquema."}],"secciones":[{"titulo":"Clasificación","parrafos":["La hipoglucemia se clasifica en nivel 1 (glucosa menor de 70 mg/dL), nivel 2 (menor de 54 mg/dL) y nivel 3 (evento grave con alteración del estado mental o necesidad de asistencia). Los síntomas incluyen temblor, sudoración, palpitaciones, hambre, confusión y, en casos graves, convulsiones o coma.","La hipoglucemia grave requiere asistencia de otra persona. La educación del paciente y la familia para reconocerla y tratarla es esencial."]},{"titulo":"Causas farmacológicas","parrafos":["La insulina y las sulfonilureas son las causas farmacológicas más frecuentes. También contribuyen el ayuno, el alcohol, el ejercicio no planificado, la insuficiencia renal y las interacciones que aumentan la exposición a los antidiabéticos. Las sulfonilureas pueden causar hipoglucemias prolongadas.","El QF revisa el esquema, la dosis, el horario, la función renal y el consumo de alcohol. La hipoglucemia recurrente obliga a ajustar el tratamiento y revisar la educación."]},{"titulo":"Tratamiento y prevención","parrafos":["En el paciente consciente se aplica la regla de los 15: 15 gramos de carbohidrato de acción rápida, reevaluar a los 15 minutos y repetir si persiste. En el paciente inconsciente se usa glucagón o atención de emergencia. No se debe dar líquidos por boca a una persona inconsciente.","La prevención incluye educación, ajuste del esquema, monitoreo continuo cuando está indicado y un plan de acción. La hipoglucemia no debe normalizarse: es una señal de que el tratamiento necesita revisión."]}],"errores":[{"error":"No reevaluar la glucosa.","correccion":"Puede persistir."},{"error":"Dar líquidos a un inconsciente.","correccion":"Riesgo de aspiración."},{"error":"No ajustar el esquema.","correccion":"La hipoglucemia recurre."}],"comprueba":[{"pregunta":"¿Qué es la regla de los 15?","respuesta":"15 g y reevaluar en 15 minutos."},{"pregunta":"¿Qué fármacos la causan?","respuesta":"Insulina y sulfonilureas."},{"pregunta":"¿Qué se usa en la grave?","respuesta":"Glucagón o urgencia."}],"resumen":["La hipoglucemia tiene tres niveles.","Insulina y sulfonilureas son causas frecuentes.","La regla de los 15 guía el tratamiento.","La prevención exige ajuste y educación."],"referencias":[{"cita":"American Diabetes Association. 6. Glycemic Goals and Hypoglycemia: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Hipoglucemia","descripcion":"Síntomas, niveles y regla de los 15.","alt":"Hipoglucemia y regla de los 15"}],"keywords":["hipoglucemia","regla de los 15","glucagón","sulfonilureas"],"mapa":{"centro":"Hipoglucemia","ramas":[{"titulo":"Niveles","icono":"AlertTriangle","nodos":["<70","<54","Grave"]},{"titulo":"Causas","icono":"Pill","nodos":["Insulina","Sulfonilurea","Ayuno","Alcohol"]},{"titulo":"Tratamiento","icono":"Zap","nodos":["15 g","15 min","Glucagón"]},{"titulo":"Prevención","icono":"Users","nodos":["Educación","Ajuste","CGM"]}]},"proceso":{"titulo":"Manejar la hipoglucemia","intro":"","pasos":[{"titulo":"Reconocer","detalle":"Síntomas y glucosa.","icono":"AlertTriangle","evidencia":"Glucómetro."},{"titulo":"Tratar","detalle":"15 g de carbohidrato.","icono":"Zap","evidencia":"Registro."},{"titulo":"Reevaluar","detalle":"A los 15 minutos.","icono":"Timer","evidencia":"Glucosa."},{"titulo":"Grave","detalle":"Glucagón o urgencia.","icono":"Syringe","evidencia":"Plan."},{"titulo":"Prevenir","detalle":"Ajuste y educación.","icono":"Users","evidencia":"Seguimiento."}]},"caso":{"titulo":"Glucosa de 55","contexto":"Paciente consciente con temblor y glucosa de 55 mg/dL.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"15 g de carbohidrato y reevaluar en 15 min.","correcta":true,"retro":"Es la regla de los 15."},{"texto":"Esperar a que pase.","correcta":false,"retro":"Puede empeorar."},{"texto":"Administrar insulina.","correcta":false,"retro":"Agravaría la hipoglucemia."}]}}$j$::jsonb;
