  -- 08. Caso: rol del QF en la educación del paciente con DM1 en insulinoterapia
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La educación que evita la próxima hipoglucemia","texto":"Una joven con DM1 tiene hipoglucemias nocturnas, errores de conteo y no lleva glucagón. La educación estructurada del QF puede cambiar su seguridad y su control. El caso integra técnica, conteo, hipoglucemia y sick day rules."},"objetivos":["Aplicar educación estructurada en DM1.","Corregir técnica y conteo.","Prevenir hipoglucemias.","Diseñar un plan de seguimiento."],"conceptos":[{"icono":"GraduationCap","termino":"Educación","definicion":"Conocimiento y habilidades prácticas."},{"icono":"Calculator","termino":"Conteo","definicion":"Relación insulina-carbohidrato."},{"icono":"AlertTriangle","termino":"Hipoglucemia","definicion":"Riesgo del esquema basal-bolo."},{"icono":"FileCheck","termino":"Sick day","definicion":"Plan para días de enfermedad."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente tiene diabetes tipo 1, esquema basal-bolo, hipoglucemias nocturnas y errores en el conteo de carbohidratos. No lleva glucagón y no sabe qué hacer en días de enfermedad. La revisión de la técnica muestra que no rota los sitios y que a veces omite el bolo.","El QF evalúa conocimientos, habilidades y barreras. La educación debe ser práctica y adaptada a la edad y al estilo de vida. La participación de la familia o la pareja mejora la seguridad."]},{"titulo":"Intervención","parrafos":["Se corrige la técnica, se acuerda la rotación de sitios y se revisa el conteo con ejemplos reales. Se ajusta el plan de hipoglucemia con la regla de los 15 y se prescribe glucagón. Se explican las reglas de días de enfermedad: nunca suspender la insulina basal, monitorear más y consultar si hay vómito o cetonas.","Se revisan las dosis con el equipo y se acuerda un registro de glucosa y carbohidratos. La educación se documenta y se refuerza en cada contacto."]},{"titulo":"Seguimiento","parrafos":["El control incluye revisión de la glucosa, el tiempo en rango, las hipoglucemias y la técnica. La monitorización continua puede ayudar a identificar patrones nocturnos. La HbA1c se mide cada tres a seis meses.","El caso muestra que la educación no es un folleto: es una intervención clínica que reduce eventos y mejora la calidad de vida. El QF es un actor clave en ese proceso."]}],"errores":[{"error":"No revisar la técnica.","correccion":"Afecta la absorción."},{"error":"No prescribir glucagón.","correccion":"Falta seguridad en la grave."},{"error":"Suspender la basal en enfermedad.","correccion":"Riesgo de cetoacidosis."}],"comprueba":[{"pregunta":"¿Qué es la regla de los 15?","respuesta":"15 g y reevaluar en 15 minutos."},{"pregunta":"¿Se suspende la basal en enfermedad?","respuesta":"No."},{"pregunta":"¿Qué se revisa en el seguimiento?","respuesta":"Glucosa, TIR y técnica."}],"resumen":["La educación en DM1 es clínica.","La técnica y el conteo se revisan.","El glucagón es parte del plan.","El seguimiento refuerza la seguridad."],"referencias":[{"cita":"American Diabetes Association. 5. Facilitating Positive Health Behaviors and Well-being: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"American Diabetes Association. 7. Diabetes Technology: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Plan educativo para una persona con DM1.","alt":"Educación del paciente con DM1 en insulinoterapia"}],"keywords":["educación dm1","insulinoterapia","conteo carbohidratos","glucagón"],"mapa":{"centro":"Educación DM1","ramas":[{"titulo":"Técnica","icono":"Eye","nodos":["Inyección","Rotación","Pluma"]},{"titulo":"Conteo","icono":"Calculator","nodos":["Carbohidratos","Corrección","Registro"]},{"titulo":"Hipoglucemia","icono":"AlertTriangle","nodos":["Regla 15","Glucagón","Nocturna"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["CGM","HbA1c","Plan"]}]},"proceso":{"titulo":"Educación en DM1","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Conocimientos y barreras.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Corregir","detalle":"Técnica y conteo.","icono":"Eye","evidencia":"Práctica."},{"titulo":"Prevenir","detalle":"Hipoglucemia y glucagón.","icono":"AlertTriangle","evidencia":"Plan."},{"titulo":"Enfermedad","detalle":"Reglas de días de enfermedad.","icono":"FileCheck","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Registro y control.","icono":"CalendarClock","evidencia":"Consulta."}]},"caso":{"titulo":"Hipoglucemias nocturnas","contexto":"Joven con DM1, basal-bolo, hipoglucemias nocturnas, errores de conteo y sin glucagón.","pregunta":"¿Qué prioriza el QF?","opciones":[{"texto":"Solo aumentar la insulina.","correcta":false,"retro":"Empeora las hipoglucemias."},{"texto":"Técnica, conteo y plan de hipoglucemia.","correcta":true,"retro":"Aborda las causas y la seguridad."},{"texto":"Suspender la basal.","correcta":false,"retro":"Riesgo de cetoacidosis."}]}}$j$::jsonb;
