  -- 09. Introducción a la unidad: del control glucémico al beneficio cardiorrenal
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Más allá de la glucosa","texto":"Dos pacientes con la misma HbA1c pueden tener pronósticos distintos según su enfermedad cardiovascular, renal o cardíaca. La elección del antidiabético ya no depende solo de la glucosa: depende del riesgo."},"objetivos":["Reconocer el beneficio cardiorrenal.","Aplicar la elección por comorbilidad.","Ubicar los grupos de fármacos.","Conectar la evidencia con la práctica."],"conceptos":[{"icono":"Activity","termino":"ASCVD","definicion":"Enfermedad aterosclerótica."},{"icono":"Droplets","termino":"ERC","definicion":"Enfermedad renal crónica."},{"icono":"ShieldCheck","termino":"IC","definicion":"Insuficiencia cardíaca."},{"icono":"Target","termino":"Elección","definicion":"Según comorbilidad y meta."}],"secciones":[{"titulo":"El cambio de paradigma","parrafos":["La elección del tratamiento de la DM2 se centra en las comorbilidades. En enfermedad aterosclerótica o alto riesgo se usan agonistas GLP-1 y/o iSGLT2 con beneficio demostrado, independientemente de la HbA1c. En insuficiencia cardíaca se indica un iSGLT2. En enfermedad renal crónica con albuminuria se usan iSGLT2 y, según el caso, GLP-1.","La metformina sigue siendo útil, pero no es el único punto de partida. La evidencia de beneficio cardiorrenal cambió la forma de elegir y de educar."]},{"titulo":"Los grupos","parrafos":["Los iSGLT2 reducen hospitalización por IC y progresión renal. Los agonistas GLP-1 reducen eventos cardiovasculares y peso; la semaglutida y la tirzepatida tienen evidencia destacada. Los inhibidores de DPP-4 son neutros desde el punto de vista cardiovascular y útiles en algunos perfiles. La insulina sigue siendo necesaria en muchos pacientes.","La elección depende del riesgo, la tolerancia, el costo y el acceso. El QF revisa la coherencia entre la comorbilidad y el fármaco."]},{"titulo":"Aplicación","parrafos":["El QF identifica la comorbilidad, revisa si el paciente recibe el fármaco con beneficio y detecta barreras. También educa sobre los beneficios y los efectos adversos, y coordina el acceso.","La glucosa sigue importando, pero el riesgo cardiovascular y renal es el marco de la decisión. La unidad desarrolla esta lógica con casos y evidencia. La revisión debe actualizarse, porque las indicaciones y la cobertura cambian con el tiempo. El QF documenta la justificación de cada elección y facilita la continuidad entre niveles de atención."]}],"errores":[{"error":"Elegir solo por HbA1c.","correccion":"La comorbilidad importa."},{"error":"No revisar el acceso.","correccion":"La continuidad depende de él."},{"error":"Ignorar la evidencia.","correccion":"Los grupos no son equivalentes."}],"comprueba":[{"pregunta":"¿Qué fármaco beneficia la IC?","respuesta":"El iSGLT2."},{"pregunta":"¿Qué grupo reduce eventos ateroscleróticos?","respuesta":"Los agonistas GLP-1."},{"pregunta":"¿Qué guía respalda la elección?","respuesta":"La ADA 2026."}],"resumen":["La elección depende de la comorbilidad.","Los iSGLT2 y GLP-1 tienen beneficio.","La metformina no es el único inicio.","El acceso condiciona la práctica."],"referencias":[{"cita":"American Diabetes Association. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://doi.org/10.2337/dc26-S009"}],"imagenes":[{"ubicacion":"Unidad 2","descripcion":"Comorbilidad y fármaco con beneficio.","alt":"Beneficio cardiorrenal de los antidiabéticos"}],"keywords":["beneficio cardiorrenal","isglt2","glp-1","elección dm2"],"mapa":{"centro":"Beneficio cardiorrenal","ramas":[{"titulo":"ASCVD","icono":"Activity","nodos":["GLP-1","SGLT2"]},{"titulo":"IC","icono":"ShieldCheck","nodos":["SGLT2","GLP-1 en obesidad"]},{"titulo":"ERC","icono":"Droplets","nodos":["SGLT2","GLP-1","Nefroprotección"]},{"titulo":"Obesidad","icono":"Scale","nodos":["GLP-1","Tirzepatida"]}]},"proceso":{"titulo":"Elegir por comorbilidad","intro":"","pasos":[{"titulo":"Riesgo","detalle":"ASCVD, IC o ERC.","icono":"ClipboardList","evidencia":"Ficha."},{"titulo":"Meta","detalle":"HbA1c y peso.","icono":"Target","evidencia":"Plan."},{"titulo":"Fármaco","detalle":"Beneficio demostrado.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Acceso","detalle":"Cobertura y costo.","icono":"FileCheck","evidencia":"Gestión."},{"titulo":"Seguir","detalle":"Efecto y seguridad.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"DM2 con insuficiencia cardíaca","contexto":"Paciente con DM2 e insuficiencia cardíaca que solo recibe metformina.","pregunta":"¿Qué fármaco aporta beneficio?","opciones":[{"texto":"Un iSGLT2.","correcta":true,"retro":"Reduce hospitalización por IC."},{"texto":"Una sulfonilurea.","correcta":false,"retro":"No tiene ese beneficio."},{"texto":"Suspender todo.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
