  -- 10. Metformina: mecanismo, farmacocinética, función renal y seguridad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La metformina y el contraste","texto":"Un paciente con ERC recibe metformina y se programa para una tomografía con contraste. La revisión de la función renal y la suspensión temporal previenen la acidosis láctica. La metformina es segura cuando se usa con criterio."},"objetivos":["Explicar el mecanismo.","Aplicar la dosis y el ajuste renal.","Reconocer la acidosis láctica.","Educar sobre efectos digestivos y B12."],"conceptos":[{"icono":"Database","termino":"AMPK","definicion":"Vía que reduce la gluconeogénesis."},{"icono":"Droplets","termino":"TFG","definicion":"Guía el ajuste y la suspensión."},{"icono":"AlertTriangle","termino":"Acidosis","definicion":"Rara pero grave."},{"icono":"TestTube","termino":"B12","definicion":"Puede reducirse con uso prolongado."}],"secciones":[{"titulo":"Mecanismo y dosis","parrafos":["La metformina reduce la producción hepática de glucosa y mejora la sensibilidad periférica. No estimula la secreción de insulina, por lo que rara vez causa hipoglucemia en monoterapia. Se inicia con 500 mg una o dos veces al día con las comidas y se titula hasta 2000 mg al día según tolerancia.","La presentación de liberación prolongada mejora los síntomas digestivos. La metformina es eficaz, económica y con amplia experiencia de uso."]},{"titulo":"Función renal","parrafos":["La metformina se elimina por vía renal. Con TFG entre 30 y 45 mL/min se usa con precaución y dosis menores; con TFG menor de 30 se contraindica. Se suspende antes de estudios con contraste y en situaciones de riesgo de lesión renal aguda, y se reinicia cuando la función es estable.","La revisión de la TFG es obligatoria antes de iniciar y durante el seguimiento. El QF verifica la fecha del último laboratorio y las condiciones clínicas."]},{"titulo":"Seguridad","parrafos":["Los efectos digestivos son frecuentes al inicio: diarrea, náuseas, dolor abdominal y sabor metálico. Suelen mejorar con titulación lenta y con la presentación de liberación prolongada. El uso prolongado puede reducir la vitamina B12 y causar anemia o neuropatía; se considera su medición en pacientes de riesgo.","La acidosis láctica es rara pero grave. Se sospecha en pacientes con deterioro renal, hipoxia, sepsis, alcoholismo o insuficiencia hepática. La educación incluye suspenderla en enfermedad aguda y consultar."]}],"errores":[{"error":"No revisar la TFG.","correccion":"La dosis depende de ella."},{"error":"Ignorar los síntomas digestivos.","correccion":"Afectan la adherencia."},{"error":"No considerar la B12.","correccion":"Puede causar anemia."}],"comprueba":[{"pregunta":"¿Qué hace la metformina?","respuesta":"Reduce la producción hepática de glucosa."},{"pregunta":"¿Cuándo se contraindica?","respuesta":"Con TFG menor de 30."},{"pregunta":"¿Qué se suspende ante contraste?","respuesta":"La metformina, temporalmente."}],"resumen":["La metformina es eficaz y segura con criterio.","La TFG guía el ajuste.","La acidosis láctica es rara pero grave.","La B12 y los síntomas digestivos se vigilan."],"referencias":[{"cita":"American Diabetes Association. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://doi.org/10.2337/dc26-S009"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/69294/FT_69294.html"}],"imagenes":[{"ubicacion":"Metformina","descripcion":"Ajuste renal y seguridad de la metformina.","alt":"Metformina mecanismo y seguridad"}],"keywords":["metformina","metformina tfg","acidosis láctica","vitamina b12"],"mapa":{"centro":"Metformina","ramas":[{"titulo":"Mecanismo","icono":"Database","nodos":["Hígado","AMPK","Gluconeogénesis"]},{"titulo":"Dosis","icono":"Pill","nodos":["500 mg","2000 mg","Con comida"]},{"titulo":"Renal","icono":"Droplets","nodos":["TFG 45","TFG 30","Suspender"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Digestivo","B12","Láctica"]}]},"proceso":{"titulo":"Checklist de metformina","intro":"","pasos":[{"titulo":"Indicación","detalle":"DM2 y riesgo.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Renal","detalle":"TFG actual.","icono":"Droplets","evidencia":"Laboratorio."},{"titulo":"Dosis","detalle":"Titulación lenta.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Seguridad","detalle":"Digestivo y B12.","icono":"AlertTriangle","evidencia":"Entrevista."},{"titulo":"Suspender","detalle":"Contraste o enfermedad aguda.","icono":"XCircle","evidencia":"Plan."}]},"caso":{"titulo":"Contraste y metformina","contexto":"Paciente con TFG de 40 y metformina programado para tomografía con contraste.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Mantener la metformina.","correcta":false,"retro":"Hay riesgo de lesión renal."},{"texto":"Suspender temporalmente y reiniciar si la función es estable.","correcta":true,"retro":"Previene la acidosis."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Nunca."}]}}$j$::jsonb;
